constexpr int32 MaxGraphs = 256, MaxNodes = 2048, MaxParameters = 128;
bool Fail(FResult& R, const TCHAR* Code, const FString& Message) { R.ErrorCode = Code; R.Error = Message; return false; }
FString Text(const TSharedRef<FJsonObject>& J) { FString Out; FJsonSerializer::Serialize(J, TJsonWriterFactory<>::Create(&Out)); return Out; }
void Merge(FJsonObject& Out, const FJsonObject& From) { for (const auto& Pair : From.Values) { Out.SetField(FString(Pair.Key.ToView()), Pair.Value); } }
// UE5.8.3-58210709 observations: engine-capture-signatures-AC1-r2.json,
// plus exact Add_VectorVector from engine-particle-receiver-signatures-AD4.json.
// BreakRotator/BreakTransform use engine-array-native-support-AG2.json.
// MakeVector and the two Vector-array calls use engine-vector-signatures-AQ1.json.
// The two RandomStream functions use engine-stream-signatures-AR2.json.
// The thirteen spline/scene/pose functions use engine-spline-signatures-AU1.json.
// The fourteen ISM/mesh/bounds/fitting functions use engine-ism-signatures-AV1.json.
// JW interpolation entries below are installed SDK expectations, not prior runtime captures.
// These are complete exact contracts, not a class/struct/reference allowance.
struct FNativeCaptureParameter
{
    const TCHAR* Name; const TCHAR* FieldClass; const TCHAR* CppType; uint64 Flags;
    const TCHAR* Category; const TCHAR* Subcategory; const TCHAR* TypeObject;
    bool bReference; bool bConst; bool bInput;
    EPinContainerType ContainerType = EPinContainerType::None;
    uint64 ArrayInnerFlags = 0;
    bool bCppDefaultPresent = false;
    const TCHAR* CppDefault = TEXT("");
};
struct FNativeCaptureSignature
{
    const TCHAR* ClassPath; const TCHAR* FunctionName; uint32 Flags;
    const FNativeCaptureParameter* Parameters; int32 Count;
    bool bPose = false;
    bool bConveyor = false;
    bool bSourceMakeStruct = false;
    bool bInterpolation = false;
    bool bPhysicsAuthoring = false;
    bool bFacing = false;
    bool bSceneCamera = false;
    bool bCameraProvider = false;
    bool bShapeBounds = false;
    bool bComponentControl = false;
    bool bComponentLifecycle = false;
    bool bConveyorPlacement = false;
    bool bActorMotion = false;
    bool bMaterialGraph = false;
    bool bMaterialWorkflow = false;
    bool bVector4Make = false;
    bool bNiagaraTouch = false;
    bool bRenderTargetGraph = false;
    bool bNiagaraLifecycleGraph = false;
    bool bTouchTraceGraph = false;
    bool bAssetRegistryGraph = false;
    bool bCameraViewGraph = false;
    bool bComponentFilterGraph = false;
    bool bBoneSocketGraph = false;
    bool bTrackerCoordinateGraph = false;
    bool bAssetSearchGraph = false; // LX exact4, symbolic SDK profile with full current numeric receipts.
    bool bPresetNormalization = false;
};
