FResult Resolve(const FString& Path, const FString& Name, const FString& Id, const FString& Type, bool bCreate)
{
    FResult R; R.Data->SetBoolField(TEXT("resolved"), false); R.Data->SetBoolField(TEXT("created"), false);
    UBlueprint* BP = Load(Path, R); if (!BP) { return R; } R.Data->SetStringField(TEXT("blueprint"), BP->GetPathName());
    UEdGraph* G = FindGraph(BP, Name, Id, Type, R, bCreate); if (!R.ErrorCode.IsEmpty()) { return R; }
    if(!G&&bCreate&&BP->BlueprintType==BPTYPE_FunctionLibrary&&!Name.Equals(TEXT("CameraFacing"),ESearchCase::CaseSensitive)&&!Name.Equals(TEXT("PresetLoader"),ESearchCase::CaseSensitive))return ResolveGenericLibrary(BP,Name,Id,Type,MoveTemp(R));
    TSharedPtr<FDeclarationEnumScope> LibraryScope;
    if(BP->BlueprintType==BPTYPE_FunctionLibrary&&((G&&(G->GetFName()==TEXT("CameraFacing")||G->GetFName()==TEXT("PresetLoader")))||(!G&&bCreate&&(Name.Equals(TEXT("CameraFacing"),ESearchCase::CaseSensitive)||Name.Equals(TEXT("PresetLoader"),ESearchCase::CaseSensitive)))))
    {const bool Preset=G?G->GetFName()==TEXT("PresetLoader"):Name.Equals(TEXT("PresetLoader"),ESearchCase::CaseSensitive);LibraryScope=MakeShared<FDeclarationEnumScope>();if(!LibraryScope->BeginLibrary(FEdGraphPinType(),R,Preset)||!LibraryScope->BindBlueprint(BP)||(G&&!LibraryScope->BindGraph(G)))return R;}
    TSharedRef<FJsonObject> Before = MakeShared<FJsonObject>(); if (!Capture(BP,G,Before,R,LibraryScope.Get())) { return R; } R.Data->SetObjectField(TEXT("before"), Before);
    if (G)
    {
        R.Data->SetBoolField(TEXT("resolved"), true); R.Data->SetObjectField(TEXT("graph"), DescribeGraph(BP, G)); After(BP,G,Before,R,LibraryScope.Get());
        R.bSuccess = R.bPostconditionPassed = R.bChangeStateKnown && !R.bChanged; R.Stage = R.bSuccess ? TEXT("complete") : TEXT("verification"); return R;
    }
    if (!bCreate) { Fail(R, TEXT("function_graph_not_found"), TEXT("Graph not found.")); return R; }
    if (!Id.IsEmpty() || NormalizeType(Type) != TEXT("function")) { Fail(R, TEXT("function_graph_creation_unsupported"), TEXT("Create requires graph_type=function, an exact name, and no graph_id.")); return R; }
    if (Before->GetArrayField(TEXT("graphs")).Num() >= MaxGraphs || !CheckNewName(BP, Name, R) || !MutationScope(BP,R,LibraryScope.Get()))
    { if (R.ErrorCode.IsEmpty()) { Fail(R, TEXT("function_graph_budget_exceeded"), TEXT("Creating a graph would exceed the graph budget.")); } return R; }
    R.Stage = TEXT("create_graph"); R.bMutationAttempted = true; BP->Modify();if(LibraryScope&&!LibraryScope->Check())return R;
    G = FBlueprintEditorUtils::CreateNewGraph(BP, FName(*Name), UEdGraph::StaticClass(), UEdGraphSchema_K2::StaticClass());
    TStrongObjectPtr<UEdGraph> ReturnedLibraryGraph;
    if(LibraryScope){R.Data->SetBoolField(TEXT("function_library_create_graph_returned_nonnull"),G!=nullptr);if(G&&IsInGameThread()&&!IsGarbageCollecting()&&!UE::IsSavingPackage()&&!GExitPurge&&IsValid(G)){ReturnedLibraryGraph.Reset(G);R.Data->SetStringField(TEXT("function_library_returned_graph_path"),G->GetPathName());}if(!LibraryScope->Check())return R;}
    if (!G) { After(BP, nullptr, Before, R); Fail(R, TEXT("function_graph_creation_failed"), TEXT("CreateNewGraph returned null; inspect observed changes before retry.")); return R; }
    FBlueprintEditorUtils::AddFunctionGraph<UFunction>(BP, G, true, nullptr); R.Data->SetBoolField(TEXT("implicit_skeleton_compile_possible"), true);
    if(LibraryScope){R.Data->SetBoolField(TEXT("function_library_add_function_graph_returned"),true);if(!LibraryScope->RefreshClasses()||!LibraryScope->BindGraph(G))return R;}
    After(BP,G,Before,R,LibraryScope.Get()); TArray<UK2Node_FunctionEntry*> Entries; G->GetNodesOfClass(Entries);if(LibraryScope&&!LibraryScope->Check())return R;
    R.Data->SetBoolField(TEXT("created"), BP->FunctionGraphs.Contains(G)); R.Data->SetBoolField(TEXT("resolved"), BP->FunctionGraphs.Contains(G)); R.Data->SetObjectField(TEXT("graph"), DescribeGraph(BP, G));
    if (Entries.Num() == 1) { R.Data->SetObjectField(TEXT("entry_node"), DescribeNode(Entries[0],LibraryScope.Get())); }
    bool Valid = R.bChangeStateKnown && G->GetName() == Name && BP->FunctionGraphs.Contains(G) && Entries.Num() == 1 && G->Nodes.Num() == 1;
    const auto& OldGraphs = Before->GetArrayField(TEXT("graphs")); TArray<UEdGraph*> All; BP->GetAllGraphs(All); Valid &= All.Num() == OldGraphs.Num() + 1;
    for (const auto& V : OldGraphs)
    { const auto J = V->AsObject(); UEdGraph* Old = FindObject<UEdGraph>(nullptr, *J->GetStringField(TEXT("object_path"))); Valid &= Old && All.Contains(Old) && Text(DescribeGraph(BP, Old)) == Text(J.ToSharedRef()); }
    if(LibraryScope){if(!LibraryScope->Check()||Entries.Num()!=1||!LibraryScope->Library->WorldPin(Entries[0]))return R;R.Data->SetBoolField(TEXT("function_library_static_graph_authoring"),true);R.Data->SetBoolField(TEXT("runtime_invocation_verified"),false);}
    if (!Valid) { R.Stage = TEXT("verification"); Fail(R, TEXT("function_graph_postcondition_failed"), TEXT("Created graph/entry identity or preservation check failed; no rollback is claimed.")); return R; }
    R.bSuccess = R.bPostconditionPassed = true; R.Stage = TEXT("complete"); return R;
}

