namespace { FResult AddReturnCreatingGraph(const FString&,const FString&,const FString&,const FString&,const FString&); }

FResult AddReturn(const FString& Path, const FString& PositionJson, const FString& GraphName,
    const FString& GraphId, const FString& RequestedGraphType, bool bCreateGraph)
{
    FResult R;
    if (bCreateGraph)
    { return AddReturnCreatingGraph(Path,PositionJson,GraphName,GraphId,RequestedGraphType); }
    int32 Position[2] = {320, 0};
    if (!PositionJson.IsEmpty())
    {
        TSharedPtr<FJsonValue> Value; if (!Pin::ParseJson(PositionJson, Value, R)) { return R; }
        if (Value->Type != EJson::Null)
        {
            if (Value->Type != EJson::Array || Value->AsArray().Num() != 2)
            { Fail(R, TEXT("function_position_invalid"), TEXT("node_position must be null or exactly two int32 JSON coordinates.")); return R; }
            for (int32 I = 0; I < 2; ++I)
            {
                const auto& V = Value->AsArray()[I]; const double N = V->Type == EJson::Number ? V->AsNumber() : MAX_dbl;
                if (V->Type != EJson::Number || N < MIN_int32 || N > MAX_int32 || FMath::TruncToDouble(N) != N)
                { Fail(R, TEXT("function_position_invalid"), TEXT("Return coordinates require exact int32 JSON numbers, excluding booleans/fractional truncation.")); return R; }
                Position[I] = static_cast<int32>(N);
            }
        }
    }
    UBlueprint* BP = Load(Path, R); if (!BP) { return R; } TStrongObjectPtr<UBlueprint> Keep(BP);
    UEdGraph* G = FindGraph(BP, GraphName, GraphId, RequestedGraphType, R); if (!G) { return R; }
    if (GraphType(BP, G) != TEXT("function"))
    { Fail(R, TEXT("function_graph_type_unsupported"), TEXT("Return nodes require a locally owned function graph.")); return R; }
    TSharedPtr<FDeclarationEnumScope> EnumScope;
    if(BP->BlueprintType==BPTYPE_FunctionLibrary){EnumScope=MakeShared<FDeclarationEnumScope>();if(!EnumScope->BeginLibrary(FEdGraphPinType(),R,G->GetFName()==TEXT("PresetLoader"))||!EnumScope->BindBlueprint(BP)||!EnumScope->BindGraph(G))return R;}
    TSharedRef<FJsonObject> Before = MakeShared<FJsonObject>();
    if (!Capture(BP,G,Before,R,EnumScope.Get()) || !MutationScope(BP,R,EnumScope.Get())) { return R; }
    R.Data->SetObjectField(TEXT("before"), Before); FResultTarget Target;
    if (!InspectResultTarget(BP,G,false,Target,R,EnumScope.Get())) { return R; }
    if(EnumScope&&(!EnumScope->BindEditable(Target.Entry)||(Target.Existing&&!EnumScope->BindEditable(Target.Existing))))return R;
    if (Target.Existing)
    {
        auto PriorPosition = MakeShared<FJsonObject>(); PriorPosition->SetNumberField(TEXT("x"), Target.Existing->NodePosX);
        PriorPosition->SetNumberField(TEXT("y"), Target.Existing->NodePosY); R.Data->SetObjectField(TEXT("position_before"), PriorPosition);
    }
    else { R.Data->SetField(TEXT("position_before"), MakeShared<FJsonValueNull>()); }
    R.Stage = TEXT("add_return"); R.bMutationAttempted = true; BP->Modify();if(EnumScope&&!EnumScope->Check())return R;G->Modify();if(EnumScope&&!EnumScope->Check())return R;Target.Entry->Modify();if(EnumScope&&!EnumScope->Check())return R;
    UK2Node_FunctionResult* Result = FBlueprintEditorUtils::FindOrCreateFunctionResultNode(Target.Entry);
    if(EnumScope&&EnumScope->Library&&EnumScope->Library->PresetLoader)EnumScope->Library->PresetReturnedNode(Result);
    TStrongObjectPtr<UK2Node_FunctionResult> ReturnedLibraryResult;
    if(EnumScope&&Result&&IsInGameThread()&&!IsGarbageCollecting()&&!UE::IsSavingPackage()&&!GExitPurge&&DeclarationEnumLoaded(Result))ReturnedLibraryResult.Reset(Result);
    if(EnumScope){R.Data->SetBoolField(TEXT("function_library_return_helper_returned_nonnull"),Result!=nullptr);if(Result&&IsInGameThread()&&!IsGarbageCollecting()&&!UE::IsSavingPackage()&&!GExitPurge&&IsValid(Result))R.Data->SetStringField(TEXT("function_library_returned_result_path"),Result->GetPathName());if(!EnumScope->BindEditable(Result))return R;}
    if (IsValid(Result))
    { Result->Modify();if(EnumScope&&!EnumScope->Check())return R;Result->NodePosX = Position[0]; Result->NodePosY = Position[1]; Result->ReconstructNode();if(EnumScope&&!EnumScope->Check())return R; }
    FBlueprintEditorUtils::MarkBlueprintAsModified(BP);if(EnumScope&&!EnumScope->Check())return R;After(BP,G,Before,R,EnumScope.Get());if(EnumScope&&!EnumScope->Check())return R;
    bool Verified = RecordResultOutcome(BP,G,Target,Result,Before,false,true,R,EnumScope.Get())
        && IsValid(Result) && Result->NodePosX == Position[0] && Result->NodePosY == Position[1];
    if (Target.Existing && IsValid(Result))
    { Verified &= Text(R.Data->GetObjectField(TEXT("return_identity_before")).ToSharedRef()) == Text(ResultIdentity(Result,EnumScope.Get())); }
    const auto* Schema = GetDefault<UEdGraphSchema_K2>();
    if (IsValid(Result)) { for (const UEdGraphPin* Pin : Result->Pins)
    { Verified &= Pin && !Pin->WasTrashed() && !Pin->bOrphanedPin && (Pin->PinType.PinCategory == UEdGraphSchema_K2::PC_Exec || Schema->IsCurrentPinDefaultValid(Pin).IsEmpty()); } }
    R.Data->SetBoolField(TEXT("implicit_skeleton_compile_possible"), false);
    R.Data->SetBoolField(TEXT("implicit_skeleton_compile_requested"), false);
    R.Data->SetBoolField(TEXT("runtime_invocation_verified"), false);
    R.Data->SetStringField(TEXT("effect_scope"), TEXT("new Return or first existing Return reconstruction/reposition; only a new Return may implicitly wire an unoccupied Entry exec pin; no explicit full compile or save"));
    if(EnumScope&&(!EnumScope->Check()||!EnumScope->Library->WorldPin(Target.Entry)))return R;
    if (!Verified)
    { R.Stage = TEXT("verification"); Fail(R, TEXT("function_return_postcondition_failed"), TEXT("Return identity/reposition/default/implicit edge or existing graph preservation failed; inspect retained before/after changes, no rollback or automatic retry.")); return R; }
    R.bSuccess = R.bPostconditionPassed = true; R.Stage = TEXT("complete"); return R;
}

