bool IsFunctionLibraryBodyStock(const FString& C,const FString& N)
{
    if(C.Equals(TEXT("/Script/Engine.KismetMathLibrary"),ESearchCase::CaseSensitive))return N==TEXT("Add_DoubleDouble")||N==TEXT("BreakRotator")||N==TEXT("ComposeRotators")||N==TEXT("FindLookAtRotation")||N==TEXT("MakeRotator")||N==TEXT("SelectRotator");
    return (C.Equals(TEXT("/Script/Engine.Actor"),ESearchCase::CaseSensitive)&&N==TEXT("K2_GetActorLocation"))||(C.Equals(TEXT("/Script/Engine.GameplayStatics"),ESearchCase::CaseSensitive)&&N==TEXT("GetPlayerCameraManager"))||(C.Equals(TEXT("/Script/Engine.PlayerCameraManager"),ESearchCase::CaseSensitive)&&N==TEXT("GetCameraRotation"))||(C.Equals(TEXT("/Script/Engine.SceneComponent"),ESearchCase::CaseSensitive)&&(N==TEXT("K2_GetComponentLocation")||N==TEXT("K2_SetWorldRotation")));
}
