    const FName Name(*N);return (C.Equals(TEXT("/Script/Engine.KismetStringLibrary"),ESearchCase::CaseSensitive)&&(Name==TEXT("Conv_NameToString")||Name==TEXT("Concat_StrStr")||Name==TEXT("Contains")))||(C.Equals(TEXT("/Script/Engine.DataTableFunctionLibrary"),ESearchCase::CaseSensitive)&&Name==TEXT("GetDataTableRowNames"));
