bool IsPresetIntEqualityStock(const FString& C,const FString& N){return FindPresetIntEqualitySignature(C,N)!=nullptr;}
bool IsPresetValidityStock(const FString& C,const FString& N)
{return C.Equals(TEXT("/Script/Engine.KismetSystemLibrary"),ESearchCase::CaseSensitive)&&FName(*N)==TEXT("IsValid");}
