    N->NodePosX=Pos[0];N->NodePosY=Pos[1];N->CreateNewGuid();S.NodeGuid=N->NodeGuid;S.GuidSet=true;
    R.Data->SetStringField(TEXT("created_node_guid"),S.NodeGuid.ToString(EGuidFormats::Digits));
    if(!S.NodeGuid.IsValid()||!S.Check(TEXT("after_guid"))){S.Stop(TEXT("created_node_guid"));return R;}
    N->PostPlacedNewNode();if(!S.Check(TEXT("after_post_placed")))return R;
