    // Old graph/node rows were compared against their current engine state by the full Check above.
    // Reuse only that checked exact prefix; describe the new selected Class pin without a tracked arrow.
    TSharedRef<FJsonObject> AfterState=MakeShared<FJsonObject>();
    AfterState->SetStringField(TEXT("blueprint"),B->GetPathName());AfterState->SetBoolField(TEXT("dirty"),B->GetPackage()->IsDirty());
    AfterState->SetNumberField(TEXT("blueprint_status"),int32(B->Status.GetValue()));TArray<TSharedPtr<FJsonValue>> GraphRows;
    for(const auto& V:S.Before->GetArrayField(TEXT("graphs")))
    { if(V->AsObject()->GetStringField(TEXT("object_path"))==G->GetPathName())GraphRows.Add(MakeShared<FJsonValueObject>(CurrentGraph));else GraphRows.Add(V); }
    AfterState->SetArrayField(TEXT("graphs"),GraphRows);AfterState->SetObjectField(TEXT("graph"),CurrentGraph);
    TArray<TSharedPtr<FJsonValue>> NodeRows=S.Before->GetArrayField(TEXT("nodes"));NodeRows.Add(MakeShared<FJsonValueObject>(NodeRow));
    AfterState->SetArrayField(TEXT("nodes"),NodeRows);R.Data->SetObjectField(TEXT("after"),AfterState);R.Data->SetObjectField(TEXT("graph"),CurrentGraph);
    R.Data->SetStringField(TEXT("after_receipt_scope"),TEXT("Existing graph/node rows reused only after the immediately preceding full current-state equality check; selected graph and new node/current approved pin inventory observed directly. The held native Class path avoids tracked DefaultObject reads; global callback purity remains unverified."));
    R.Data->SetStringField(TEXT("blueprint"),B->GetPathName());R.Data->SetStringField(TEXT("function_class"),TEXT("/Script/Engine.Actor"));
    R.Data->SetStringField(TEXT("function_name"),TEXT("AddComponentByClass"));R.Data->SetStringField(TEXT("function_path"),S.Function->GetPathName());
    R.Data->SetStringField(TEXT("node_creation_api"),TEXT("public UK2Node_AddComponentByClass NewObject/AddNode/GUID/PostPlaced/Allocate, K2 class default callback and base virtual Reconstruct; current inventories reacquired"));
    R.Data->SetStringField(TEXT("legacy_node_class"),TEXT("/Script/BlueprintGraph.K2Node_CallFunction"));R.Data->SetBoolField(TEXT("full_legacy_function_parity"),false);
    R.Data->SetBoolField(TEXT("is_static"),false);R.Data->SetBoolField(TEXT("is_pure"),false);R.Data->SetBoolField(TEXT("is_latent"),false);
    R.Data->SetStringField(TEXT("spawn_class"),ClassPath);R.Data->SetBoolField(TEXT("manual_attachment_effective"),false);
