    R.Data->SetBoolField(TEXT("authored_deferred_pin_exists"),false);R.Data->SetBoolField(TEXT("deferred_finish_literal_applied_to_pin"),false);
    R.Data->SetStringField(TEXT("specialized_projection_difference"),TEXT("K2Node_AddComponentByClass, native selected typed ReturnValue, nonreference/nonconst RelativeTransform and no authored bDeferredFinish pin differ from legacy generic CallFunction. Only manual/deferred false compatibility is admitted; exposed spawn variables are rejected. The compiler owns internal Add/Finish expansion; no runtime function was called."));
    R.Data->SetBoolField(TEXT("relative_transform_requires_connection"),true);R.Data->SetBoolField(TEXT("endpoint_observed"),true);
    R.Data->SetBoolField(TEXT("existing_nodes_preserved"),true);R.Data->SetBoolField(TEXT("declarations_preserved"),true);
    R.Data->SetBoolField(TEXT("native_source_observed_unchanged"),true);R.Data->SetBoolField(TEXT("runtime_invocation_verified"),false);
    R.Data->SetBoolField(TEXT("implicit_skeleton_compile_possible"),true);R.Data->SetBoolField(TEXT("atomic_rollback_provided"),false);
    R.Data->SetStringField(TEXT("change_observation_scope"),TEXT("Current selected graph membership, old node/pin/link/default and declaration snapshots, native Actor function signature, selected spawn-class reflected layout and existing-CDO identity, strong identities and current context/transaction. No exposed spawn properties are admitted, so the stock class callback has no CDO property default to author. Full CDO values, disk equality, global callback purity, runtime component/attachment/registration/render/physics/child lifecycle, explicit compile/save and whole source builders are not verified."));
