// The cast editor node uses a native runtime target; no native target instance
// or class/CDO is created by this observer.
TSharedRef<FJsonObject> DynamicCastTargetSource(const FString& Path, const UClass* Class)
{
    auto J = MakeShared<FJsonObject>();
    const TCHAR* ParentPath = Path == TEXT("/Script/Engine.ChildActorComponent") ? TEXT("/Script/Engine.SceneComponent")
        : Path == TEXT("/Script/Engine.SceneComponent") ? TEXT("/Script/Engine.ActorComponent")
        : Path == TEXT("/Script/Engine.StaticMeshComponent") ? TEXT("/Script/Engine.MeshComponent") : nullptr;
    const UPackage* Package = IsValid(Class) ? Class->GetOutermost() : nullptr;
    const UClass* Parent = IsValid(Class) ? Class->GetSuperClass() : nullptr;
    const UObject* CDO = IsValid(Class) ? Class->GetDefaultObject(false) : nullptr;
    const bool Complete = ParentPath && IsValid(Class) && Package && IsValid(Parent) && IsValid(CDO);
    const bool Exact = Complete && FindObject<UClass>(nullptr, *Path) == Class && Class->GetPathName() == Path
        && Class->HasAnyClassFlags(CLASS_Native) && !Class->HasAnyClassFlags(CLASS_Interface | CLASS_Deprecated | CLASS_NewerVersionExists)
        && Class->ClassGeneratedBy == nullptr && !Class->IsEditorOnly() && Parent->GetPathName() == ParentPath
        && Parent == FindObject<UClass>(nullptr, ParentPath) && Package->GetName() == TEXT("/Script/Engine") && !Package->IsDirty()
        && !Package->HasAnyPackageFlags(PKG_EditorOnly | PKG_Developer | PKG_UncookedOnly)
        && !Class->HasAnyFlags(RF_NeedLoad | RF_NeedPostLoad | RF_NeedPostLoadSubobjects)
        && CDO->GetClass() == Class && CDO->GetOuter() == Package && CDO->HasAnyFlags(RF_ClassDefaultObject)
        && CDO->GetPathName() == TEXT("/Script/Engine.Default__") + Class->GetName()
        && !CDO->HasAnyFlags(RF_NeedLoad | RF_NeedPostLoad | RF_NeedPostLoadSubobjects);
    J->SetBoolField(TEXT("observations_complete"), Complete); J->SetBoolField(TEXT("native_identity_verified"), Exact);
    J->SetStringField(TEXT("class_path"), IsValid(Class) ? Class->GetPathName() : FString());
    J->SetStringField(TEXT("class_flags_string"), IsValid(Class) ? LexToString(static_cast<uint32>(Class->GetClassFlags())) : FString());
    J->SetStringField(TEXT("super_class_path"), IsValid(Parent) ? Parent->GetPathName() : FString());
    J->SetStringField(TEXT("package_path"), Package ? Package->GetName() : FString());
    J->SetStringField(TEXT("package_flags_string"), Package ? LexToString(static_cast<uint32>(Package->GetPackageFlags())) : FString());
    J->SetBoolField(TEXT("package_dirty"), Package && Package->IsDirty());
    J->SetStringField(TEXT("existing_cdo_path"), IsValid(CDO) ? CDO->GetPathName() : FString());
    J->SetStringField(TEXT("existing_cdo_flags_string"), IsValid(CDO) ? LexToString(static_cast<uint32>(CDO->GetFlags())) : FString());
    J->SetBoolField(TEXT("class_load_requested"), false); J->SetBoolField(TEXT("cdo_creation_requested"), false);
    return J;
}
TSharedRef<FJsonObject> DynamicCastDeclarations(UBlueprint* BP)
{
    auto J = MakeShared<FJsonObject>(); TArray<TSharedPtr<FJsonValue>> Rows;
    for (const FBPVariableDescription& Variable : BP->NewVariables)
    {
        FString Value; FBPVariableDescription::StaticStruct()->ExportText(Value, &Variable, &Variable, BP, PPF_None, nullptr);
        Rows.Add(MakeShared<FJsonValueString>(Value));
    }
    J->SetArrayField(TEXT("variables"), Rows); return J;
}
TSharedRef<FJsonObject> DynamicCastPin(const UEdGraphPin* P)
{
    auto J = MakeShared<FJsonObject>(); J->SetBoolField(TEXT("observations_complete"), P != nullptr);
    if (!P) { return J; }
    J->SetStringField(TEXT("name"), P->PinName.ToString()); J->SetStringField(TEXT("pin_id"), P->PinId.ToString(EGuidFormats::Digits));
    J->SetStringField(TEXT("direction"), P->Direction == EGPD_Input ? TEXT("input") : TEXT("output"));
    J->SetObjectField(TEXT("pin_type"), Pin::Describe(P->PinType)); J->SetBoolField(TEXT("is_const"), P->PinType.bIsConst);
    J->SetBoolField(TEXT("hidden"), P->bHidden); J->SetBoolField(TEXT("orphaned"), P->bOrphanedPin);
    J->SetBoolField(TEXT("default_value_ignored"), P->bDefaultValueIsIgnored);
    J->SetStringField(TEXT("default_value"), P->DefaultValue); J->SetStringField(TEXT("autogenerated_default_value"), P->AutogeneratedDefaultValue);
    J->SetStringField(TEXT("default_object"), P->DefaultObject ? P->DefaultObject->GetPathName() : FString());
    J->SetStringField(TEXT("default_text"), P->DefaultTextValue.ToString()); J->SetNumberField(TEXT("link_count"), P->LinkedTo.Num());
    return J;
}
bool DynamicCastPlainPin(const UEdGraphPin* P, EEdGraphPinDirection Direction, FName Category, const UObject* TypeObject)
{
    return P && P->Direction == Direction && P->PinType.PinCategory == Category && P->PinType.PinSubCategory.IsNone()
        && P->PinType.PinSubCategoryObject.Get() == TypeObject && !P->PinType.IsContainer()
        && !P->PinType.bIsReference && !P->PinType.bIsConst && !P->PinType.bIsWeakPointer && !P->PinType.bIsUObjectWrapper;
}

