FResult AddMakeStruct(const FString& BlueprintPath, const FString& StructType, const FString& PositionJson,
    const FString& GraphName, const FString& GraphId, const FString& GraphType, bool bCreateGraph)
{
    FResult R; bool InteriorNul = false;
    if (StructType.Len() <= 128) { for (int32 Index = 0; Index < StructType.Len(); ++Index) { InteriorNul |= StructType[Index] == TCHAR('\0'); } }
    if (StructType.Len() > 128 || InteriorNul)
    { Fail(R, TEXT("make_struct_type_invalid"), TEXT("Bounded original native struct helper type required.")); return R; }
    FString Kind = StructType.ToLower(); Kind.TrimStartAndEndInline(); Kind.ReplaceInline(TEXT(" "), TEXT("")); Kind.ReplaceInline(TEXT("_"), TEXT("")); Kind.ReplaceInline(TEXT("-"), TEXT(""));
    const TCHAR* FunctionName = Kind == TEXT("vector") ? TEXT("MakeVector") : Kind == TEXT("rotator") ? TEXT("MakeRotator") : Kind == TEXT("transform") ? TEXT("MakeTransform") : nullptr;
    if (!FunctionName)
    { Fail(R, TEXT("make_struct_type_unsupported"), FString::Printf(TEXT("Unsupported native struct helper type: %s"), *StructType)); return R; }
    R = AddCall(BlueprintPath, TEXT("/Script/Engine.KismetMathLibrary"), FunctionName, TEXT("{}"), PositionJson,
        GraphName, GraphId, GraphType, bCreateGraph, false, false, false, false, false);
    R.Data->SetStringField(TEXT("requested_struct_type"), StructType); R.Data->SetStringField(TEXT("struct_type"), Kind);
    R.Data->SetStringField(TEXT("helper_operation"), TEXT("make_struct"));
    R.Data->SetStringField(TEXT("legacy_implementation"), TEXT("native KismetMathLibrary helper call, not arbitrary UK2Node_MakeStruct"));
    R.Data->SetBoolField(TEXT("legacy_implicit_graph_creation_supported"), bCreateGraph);
    R.Data->SetBoolField(TEXT("legacy_loose_position_coercion_supported"), false);
    R.Data->SetBoolField(TEXT("runtime_struct_value_evaluated"), false);
    return R;
}

